INSERT INTO "traducao" ("id", "idioma", "hash_origem", "texto") VALUES
  (gen_random_uuid()::text, 'en', '9d1c35bc0063c2d5', '13 November 2026'),
  (gen_random_uuid()::text, 'en', '0a4db205367d4be0', 'Appears on the consent form: participants need to know who is responsible for the research and how to contact them (LGPD, art. 9).'),
  (gen_random_uuid()::text, 'en', 'ec3869e76f1392d0', 'These appear on the consent form. The tool suggests a text: adjust it to what your study requires.'),
  (gen_random_uuid()::text, 'en', '14d4f1613366048b', 'The 26 questionnaire responses, the product version you evaluated, the language, the date, whether you stated you are under 18 with the authorisation of your parent or guardian and, only if the researcher turned on that step and you chose to answer, your age group, gender, education level and whether you already used the product. All of these questions have “Prefer not to answer” and can be skipped.'),
  (gen_random_uuid()::text, 'en', 'ca75ce9e25c59a83', 'Benefits'),
  (gen_random_uuid()::text, 'en', '44e56e53751000e1', 'Ethics committee (optional)'),
  (gen_random_uuid()::text, 'en', '55ac540c97278766', 'Since nothing links the responses to you, we cannot find them to show or delete them. Contact the responsible researcher, whose details are on the consent form.'),
  (gen_random_uuid()::text, 'en', '50b8d49b6a29d1b6', '4 to 6 minutes · voluntary and anonymous'),
  (gen_random_uuid()::text, 'en', 'ea58d1d62116f00e', 'Describe the benefits. If there is no direct benefit, say so.'),
  (gen_random_uuid()::text, 'en', '06c2520553868965', 'Describe the risks to participants. If they are minimal, say so.'),
  (gen_random_uuid()::text, 'en', '9269ccc0f5929fde', 'Contact email'),
  (gen_random_uuid()::text, 'en', '573fdfeb95aa92fd', 'While the researcher is carrying out the research. When the researcher deletes the study, all responses are erased.'),
  (gen_random_uuid()::text, 'en', 'ceabb049fdec4a34', 'Enter the institution of the research.'),
  (gen_random_uuid()::text, 'en', '2d507a78f7066401', 'Enter who is responsible for the research.'),
  (gen_random_uuid()::text, 'en', '77ed48b810ebea84', 'Institution'),
  (gen_random_uuid()::text, 'en', 'a86fd6d19f0a6ad6', 'Under 18s'),
  (gen_random_uuid()::text, 'en', '1909140abac17e6c', 'Under 18'),
  (gen_random_uuid()::text, 'en', '20fa6944319fc704', 'Name of the responsible researcher'),
  (gen_random_uuid()::text, 'en', '6a06a34354a2c160', 'There is no direct benefit to you. The responses help improve the evaluated product.'),
  (gen_random_uuid()::text, 'en', '5fe2fb303bbd5ee1', 'The data controller is the researcher responsible for the study, whose name and contact details are on the consent form; the tool only processes the data on their behalf.'),
  (gen_random_uuid()::text, 'en', '71f64806926ddb43', 'Participants should contact the researcher responsible for the study, whose name and contact details are on the consent form.'),
  (gen_random_uuid()::text, 'en', 'ff188e9d3660a01b', 'The risks are minimal: answering may be a little tiring or cause some discomfort. You can stop at any time.'),
  (gen_random_uuid()::text, 'en', 'e905fbd481b44379', 'For example: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'en', '5acf07dbd38b18f1', 'Responsible researcher'),
  (gen_random_uuid()::text, 'en', '8393f9735ff6ab2c', 'Researcher responsible for the study'),
  (gen_random_uuid()::text, 'en', '0d2001e6b0e04ed4', 'Responsible researcher:'),
  (gen_random_uuid()::text, 'en', '2d46c72a0dcdfbef', 'Risks and benefits'),
  (gen_random_uuid()::text, 'en', 'f42e0f1d0b3ff09a', 'Risks to participants'),
  (gen_random_uuid()::text, 'en', '81538cef7eca23ec', 'If the study was approved by an ethics committee, enter the committee’s name, the approval or CAAE number and its contact details.'),
  (gen_random_uuid()::text, 'en', 'f29c2be3f735e12d', 'They only take part with the authorisation of a parent or legal guardian, confirmed on the first screen (art. 14).'),
  (gen_random_uuid()::text, 'en', 'ead048e033cd8fa6', 'Use at most 1000 characters for the benefits.'),
  (gen_random_uuid()::text, 'en', '41bf9e0ca889a640', 'Use at most 1000 characters for the risks.'),
  (gen_random_uuid()::text, 'en', '7ff5d65d41ecafd9', 'Use at most 160 characters for the institution.'),
  (gen_random_uuid()::text, 'en', '85720a0a1823a83f', 'Use at most 500 characters for the ethics committee.'),
  (gen_random_uuid()::text, 'es', '9d1c35bc0063c2d5', '13 de noviembre de 2026'),
  (gen_random_uuid()::text, 'es', '0a4db205367d4be0', 'Aparece en el consentimiento informado: el participante necesita saber quién responde por la investigación y cómo contactar con esa persona (LGPD, art. 9).'),
  (gen_random_uuid()::text, 'es', 'ec3869e76f1392d0', 'Aparecen en el consentimiento informado. La herramienta sugiere un texto: ajústelo a lo que su estudio requiere.'),
  (gen_random_uuid()::text, 'es', '14d4f1613366048b', 'Las 26 respuestas del cuestionario, la versión del producto que evaluó, el idioma, la fecha, si declaró tener menos de 18 años con la autorización de su responsable y, solo si el investigador activó esa etapa y usted quiso responder, el grupo de edad, el género, el nivel educativo y si ya usaba el producto. Todas estas preguntas tienen “Prefiero no responder” y pueden omitirse.'),
  (gen_random_uuid()::text, 'es', 'ca75ce9e25c59a83', 'Beneficios'),
  (gen_random_uuid()::text, 'es', '44e56e53751000e1', 'Comité de ética (opcional)'),
  (gen_random_uuid()::text, 'es', '55ac540c97278766', 'Como nada vincula las respuestas con usted, no podemos localizarlas para mostrarlas o borrarlas. Hable con el investigador responsable, cuyo contacto figura en el consentimiento informado.'),
  (gen_random_uuid()::text, 'es', '50b8d49b6a29d1b6', 'De 4 a 6 minutos · voluntaria y anónima'),
  (gen_random_uuid()::text, 'es', 'ea58d1d62116f00e', 'Describa los beneficios. Si no hay un beneficio directo, indíquelo.'),
  (gen_random_uuid()::text, 'es', '06c2520553868965', 'Describa los riesgos para el participante. Si son mínimos, indíquelo.'),
  (gen_random_uuid()::text, 'es', '9269ccc0f5929fde', 'Correo electrónico de contacto'),
  (gen_random_uuid()::text, 'es', '573fdfeb95aa92fd', 'Mientras el investigador esté realizando la investigación. Cuando elimina el estudio, se borran todas las respuestas.'),
  (gen_random_uuid()::text, 'es', 'ceabb049fdec4a34', 'Indique la institución de la investigación.'),
  (gen_random_uuid()::text, 'es', '2d507a78f7066401', 'Indique quién responde por la investigación.'),
  (gen_random_uuid()::text, 'es', '77ed48b810ebea84', 'Institución'),
  (gen_random_uuid()::text, 'es', 'a86fd6d19f0a6ad6', 'Menores de 18 años'),
  (gen_random_uuid()::text, 'es', '1909140abac17e6c', 'Menos de 18 años'),
  (gen_random_uuid()::text, 'es', '20fa6944319fc704', 'Nombre del responsable'),
  (gen_random_uuid()::text, 'es', '6a06a34354a2c160', 'No hay un beneficio directo para usted. Las respuestas ayudan a mejorar el producto evaluado.'),
  (gen_random_uuid()::text, 'es', '5fe2fb303bbd5ee1', 'El responsable del tratamiento de los datos es el investigador a cargo del estudio, cuyo nombre y contacto figuran en el consentimiento informado; la herramienta solo trata los datos en su nombre.'),
  (gen_random_uuid()::text, 'es', '71f64806926ddb43', 'Los participantes deben comunicarse con el investigador responsable del estudio, cuyo nombre y contacto figuran en el consentimiento informado.'),
  (gen_random_uuid()::text, 'es', 'ff188e9d3660a01b', 'Los riesgos son mínimos: responder puede cansar un poco o causar alguna incomodidad. Puede detenerse en cualquier momento.'),
  (gen_random_uuid()::text, 'es', 'e905fbd481b44379', 'Por ejemplo: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'es', '5acf07dbd38b18f1', 'Responsable'),
  (gen_random_uuid()::text, 'es', '8393f9735ff6ab2c', 'Responsable de la investigación'),
  (gen_random_uuid()::text, 'es', '0d2001e6b0e04ed4', 'Responsable:'),
  (gen_random_uuid()::text, 'es', '2d46c72a0dcdfbef', 'Riesgos y beneficios'),
  (gen_random_uuid()::text, 'es', 'f42e0f1d0b3ff09a', 'Riesgos para el participante'),
  (gen_random_uuid()::text, 'es', '81538cef7eca23ec', 'Si el estudio fue aprobado por un comité de ética, indique el nombre del comité, el número del dictamen o CAAE y el contacto.'),
  (gen_random_uuid()::text, 'es', 'f29c2be3f735e12d', 'Solo participan con la autorización del padre, la madre o el tutor legal, confirmada en la primera pantalla (art. 14).'),
  (gen_random_uuid()::text, 'es', 'ead048e033cd8fa6', 'Use como máximo 1000 caracteres en los beneficios.'),
  (gen_random_uuid()::text, 'es', '41bf9e0ca889a640', 'Use como máximo 1000 caracteres en los riesgos.'),
  (gen_random_uuid()::text, 'es', '7ff5d65d41ecafd9', 'Use como máximo 160 caracteres en la institución.'),
  (gen_random_uuid()::text, 'es', '85720a0a1823a83f', 'Use como máximo 500 caracteres en el comité de ética.'),
  (gen_random_uuid()::text, 'fr', '9d1c35bc0063c2d5', '13 novembre 2026'),
  (gen_random_uuid()::text, 'fr', '0a4db205367d4be0', 'Figure dans le formulaire de consentement : le participant doit savoir qui répond de la recherche et comment le contacter (LGPD, art. 9).'),
  (gen_random_uuid()::text, 'fr', 'ec3869e76f1392d0', 'Figurent dans le formulaire de consentement. L’outil propose un texte : adaptez-le à ce que votre étude exige.'),
  (gen_random_uuid()::text, 'fr', '14d4f1613366048b', 'Les 26 réponses au questionnaire, la version du produit que vous avez évaluée, la langue, la date, le fait d’avoir déclaré avoir moins de 18 ans avec l’autorisation de votre représentant légal et, seulement si le chercheur a activé cette étape et que vous avez voulu répondre, la tranche d’âge, le genre, le niveau d’études et si vous utilisiez déjà le produit. Toutes ces questions proposent « Je préfère ne pas répondre » et peuvent être passées.'),
  (gen_random_uuid()::text, 'fr', 'ca75ce9e25c59a83', 'Bénéfices'),
  (gen_random_uuid()::text, 'fr', '44e56e53751000e1', 'Comité d’éthique (facultatif)'),
  (gen_random_uuid()::text, 'fr', '55ac540c97278766', 'Comme rien ne relie les réponses à vous, nous ne pouvons pas les retrouver pour les afficher ou les supprimer. Contactez le chercheur responsable, dont les coordonnées figurent dans le formulaire de consentement.'),
  (gen_random_uuid()::text, 'fr', '50b8d49b6a29d1b6', 'De 4 à 6 minutes · volontaire et anonyme'),
  (gen_random_uuid()::text, 'fr', 'ea58d1d62116f00e', 'Décrivez les bénéfices. S’il n’y a pas de bénéfice direct, indiquez-le.'),
  (gen_random_uuid()::text, 'fr', '06c2520553868965', 'Décrivez les risques pour le participant. S’ils sont minimes, indiquez-le.'),
  (gen_random_uuid()::text, 'fr', '9269ccc0f5929fde', 'E-mail de contact'),
  (gen_random_uuid()::text, 'fr', '573fdfeb95aa92fd', 'Tant que le chercheur mène la recherche. Lorsqu’il supprime l’étude, toutes les réponses sont effacées.'),
  (gen_random_uuid()::text, 'fr', 'ceabb049fdec4a34', 'Indiquez l’institution de la recherche.'),
  (gen_random_uuid()::text, 'fr', '2d507a78f7066401', 'Indiquez qui répond de la recherche.'),
  (gen_random_uuid()::text, 'fr', '77ed48b810ebea84', 'Institution'),
  (gen_random_uuid()::text, 'fr', 'a86fd6d19f0a6ad6', 'Mineurs de moins de 18 ans'),
  (gen_random_uuid()::text, 'fr', '1909140abac17e6c', 'Moins de 18 ans'),
  (gen_random_uuid()::text, 'fr', '20fa6944319fc704', 'Nom du responsable'),
  (gen_random_uuid()::text, 'fr', '6a06a34354a2c160', 'Il n’y a pas de bénéfice direct pour vous. Les réponses aident à améliorer le produit évalué.'),
  (gen_random_uuid()::text, 'fr', '5fe2fb303bbd5ee1', 'Le responsable du traitement est le chercheur responsable de l’étude, dont le nom et les coordonnées figurent dans le formulaire de consentement ; l’outil ne traite les données que pour son compte.'),
  (gen_random_uuid()::text, 'fr', '71f64806926ddb43', 'Les participants doivent contacter le chercheur responsable de l’étude, dont le nom et les coordonnées figurent dans le formulaire de consentement.'),
  (gen_random_uuid()::text, 'fr', 'ff188e9d3660a01b', 'Les risques sont minimes : répondre peut être un peu fatigant ou causer une certaine gêne. Vous pouvez arrêter à tout moment.'),
  (gen_random_uuid()::text, 'fr', 'e905fbd481b44379', 'Par exemple : PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'fr', '5acf07dbd38b18f1', 'Responsable'),
  (gen_random_uuid()::text, 'fr', '8393f9735ff6ab2c', 'Responsable de la recherche'),
  (gen_random_uuid()::text, 'fr', '0d2001e6b0e04ed4', 'Responsable :'),
  (gen_random_uuid()::text, 'fr', '2d46c72a0dcdfbef', 'Risques et bénéfices'),
  (gen_random_uuid()::text, 'fr', 'f42e0f1d0b3ff09a', 'Risques pour le participant'),
  (gen_random_uuid()::text, 'fr', '81538cef7eca23ec', 'Si l’étude a été approuvée par un comité d’éthique, indiquez le nom du comité, le numéro de l’avis ou CAAE et le contact.'),
  (gen_random_uuid()::text, 'fr', 'f29c2be3f735e12d', 'Ils ne participent qu’avec l’autorisation du père, de la mère ou du représentant légal, confirmée sur le premier écran (art. 14).'),
  (gen_random_uuid()::text, 'fr', 'ead048e033cd8fa6', 'Utilisez au maximum 1000 caractères pour les bénéfices.'),
  (gen_random_uuid()::text, 'fr', '41bf9e0ca889a640', 'Utilisez au maximum 1000 caractères pour les risques.'),
  (gen_random_uuid()::text, 'fr', '7ff5d65d41ecafd9', 'Utilisez au maximum 160 caractères pour l’institution.'),
  (gen_random_uuid()::text, 'fr', '85720a0a1823a83f', 'Utilisez au maximum 500 caractères pour le comité d’éthique.'),
  (gen_random_uuid()::text, 'de', '9d1c35bc0063c2d5', '13. November 2026'),
  (gen_random_uuid()::text, 'de', '0a4db205367d4be0', 'Erscheint in der Einwilligungserklärung: Teilnehmende müssen wissen, wer für die Studie verantwortlich ist und wie sie diese Person erreichen (LGPD, Art. 9).'),
  (gen_random_uuid()::text, 'de', 'ec3869e76f1392d0', 'Erscheinen in der Einwilligungserklärung. Die Anwendung schlägt einen Text vor: Passen Sie ihn an das an, was Ihre Studie erfordert.'),
  (gen_random_uuid()::text, 'de', '14d4f1613366048b', 'Die 26 Antworten des Fragebogens, die Version des Produkts, die Sie bewertet haben, die Sprache, das Datum, ob Sie angegeben haben, unter 18 Jahre alt zu sein und die Zustimmung Ihres gesetzlichen Vertreters zu haben, und nur wenn die Forschenden diesen Schritt aktiviert haben und Sie antworten wollten: Altersgruppe, Geschlecht, Bildungsabschluss und ob Sie das Produkt schon genutzt haben. Alle diese Fragen bieten „Keine Angabe“ und können übersprungen werden.'),
  (gen_random_uuid()::text, 'de', 'ca75ce9e25c59a83', 'Nutzen'),
  (gen_random_uuid()::text, 'de', '44e56e53751000e1', 'Ethikkommission (optional)'),
  (gen_random_uuid()::text, 'de', '55ac540c97278766', 'Da nichts die Antworten mit Ihnen verbindet, können wir sie nicht finden, um sie anzuzeigen oder zu löschen. Wenden Sie sich an die verantwortliche Person, deren Kontakt in der Einwilligungserklärung steht.'),
  (gen_random_uuid()::text, 'de', '50b8d49b6a29d1b6', '4 bis 6 Minuten · freiwillig und anonym'),
  (gen_random_uuid()::text, 'de', 'ea58d1d62116f00e', 'Beschreiben Sie den Nutzen. Wenn es keinen direkten Nutzen gibt, sagen Sie das.'),
  (gen_random_uuid()::text, 'de', '06c2520553868965', 'Beschreiben Sie die Risiken für die Teilnehmenden. Wenn sie gering sind, sagen Sie das.'),
  (gen_random_uuid()::text, 'de', '9269ccc0f5929fde', 'Kontakt-E-Mail'),
  (gen_random_uuid()::text, 'de', '573fdfeb95aa92fd', 'Solange die verantwortliche Person die Studie durchführt. Wenn sie die Studie löscht, werden alle Antworten gelöscht.'),
  (gen_random_uuid()::text, 'de', 'ceabb049fdec4a34', 'Geben Sie die Institution der Studie an.'),
  (gen_random_uuid()::text, 'de', '2d507a78f7066401', 'Geben Sie an, wer für die Studie verantwortlich ist.'),
  (gen_random_uuid()::text, 'de', '77ed48b810ebea84', 'Institution'),
  (gen_random_uuid()::text, 'de', 'a86fd6d19f0a6ad6', 'Minderjährige'),
  (gen_random_uuid()::text, 'de', '1909140abac17e6c', 'Unter 18 Jahre'),
  (gen_random_uuid()::text, 'de', '20fa6944319fc704', 'Name der verantwortlichen Person'),
  (gen_random_uuid()::text, 'de', '6a06a34354a2c160', 'Für Sie gibt es keinen direkten Nutzen. Die Antworten helfen, das bewertete Produkt zu verbessern.'),
  (gen_random_uuid()::text, 'de', '5fe2fb303bbd5ee1', 'Verantwortlich für die Daten ist die für die Studie verantwortliche Person, deren Name und Kontakt in der Einwilligungserklärung stehen; die Anwendung verarbeitet die Daten nur in deren Auftrag.'),
  (gen_random_uuid()::text, 'de', '71f64806926ddb43', 'Teilnehmende wenden sich an die für die Studie verantwortliche Person, deren Name und Kontakt in der Einwilligungserklärung stehen.'),
  (gen_random_uuid()::text, 'de', 'ff188e9d3660a01b', 'Die Risiken sind gering: Das Antworten kann etwas ermüden oder ein gewisses Unbehagen auslösen. Sie können jederzeit aufhören.'),
  (gen_random_uuid()::text, 'de', 'e905fbd481b44379', 'Zum Beispiel: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'de', '5acf07dbd38b18f1', 'Verantwortlich'),
  (gen_random_uuid()::text, 'de', '8393f9735ff6ab2c', 'Verantwortlich für die Studie'),
  (gen_random_uuid()::text, 'de', '0d2001e6b0e04ed4', 'Verantwortlich:'),
  (gen_random_uuid()::text, 'de', '2d46c72a0dcdfbef', 'Risiken und Nutzen'),
  (gen_random_uuid()::text, 'de', 'f42e0f1d0b3ff09a', 'Risiken für die Teilnehmenden'),
  (gen_random_uuid()::text, 'de', '81538cef7eca23ec', 'Wenn die Studie von einer Ethikkommission genehmigt wurde, geben Sie den Namen der Kommission, die Nummer des Votums oder CAAE und den Kontakt an.'),
  (gen_random_uuid()::text, 'de', 'f29c2be3f735e12d', 'Sie nehmen nur mit Zustimmung eines Elternteils oder des gesetzlichen Vertreters teil, bestätigt auf dem ersten Bildschirm (Art. 14).'),
  (gen_random_uuid()::text, 'de', 'ead048e033cd8fa6', 'Verwenden Sie höchstens 1000 Zeichen für den Nutzen.'),
  (gen_random_uuid()::text, 'de', '41bf9e0ca889a640', 'Verwenden Sie höchstens 1000 Zeichen für die Risiken.'),
  (gen_random_uuid()::text, 'de', '7ff5d65d41ecafd9', 'Verwenden Sie höchstens 160 Zeichen für die Institution.'),
  (gen_random_uuid()::text, 'de', '85720a0a1823a83f', 'Verwenden Sie höchstens 500 Zeichen für die Ethikkommission.'),
  (gen_random_uuid()::text, 'it', '9d1c35bc0063c2d5', '13 novembre 2026'),
  (gen_random_uuid()::text, 'it', '0a4db205367d4be0', 'Compare nel modulo di consenso: il partecipante deve sapere chi risponde della ricerca e come contattarlo (LGPD, art. 9).'),
  (gen_random_uuid()::text, 'it', 'ec3869e76f1392d0', 'Compaiono nel modulo di consenso. Lo strumento suggerisce un testo: lo adatti a ciò che il suo studio richiede.'),
  (gen_random_uuid()::text, 'it', '14d4f1613366048b', 'Le 26 risposte del questionario, la versione del prodotto che ha valutato, la lingua, la data, se ha dichiarato di avere meno di 18 anni con l’autorizzazione del genitore o tutore e, solo se il ricercatore ha attivato quella fase e lei ha voluto rispondere, la fascia d’età, il genere, il titolo di studio e se usava già il prodotto. Tutte queste domande hanno “Preferisco non rispondere” e possono essere saltate.'),
  (gen_random_uuid()::text, 'it', 'ca75ce9e25c59a83', 'Benefici'),
  (gen_random_uuid()::text, 'it', '44e56e53751000e1', 'Comitato etico (facoltativo)'),
  (gen_random_uuid()::text, 'it', '55ac540c97278766', 'Poiché nulla collega le risposte a lei, non possiamo ritrovarle per mostrarle o cancellarle. Si rivolga al ricercatore responsabile, il cui contatto è nel modulo di consenso.'),
  (gen_random_uuid()::text, 'it', '50b8d49b6a29d1b6', 'Da 4 a 6 minuti · volontaria e anonima'),
  (gen_random_uuid()::text, 'it', 'ea58d1d62116f00e', 'Descriva i benefici. Se non c’è un beneficio diretto, lo dica.'),
  (gen_random_uuid()::text, 'it', '06c2520553868965', 'Descriva i rischi per il partecipante. Se sono minimi, lo dica.'),
  (gen_random_uuid()::text, 'it', '9269ccc0f5929fde', 'E-mail di contatto'),
  (gen_random_uuid()::text, 'it', '573fdfeb95aa92fd', 'Finché il ricercatore porta avanti la ricerca. Quando elimina lo studio, tutte le risposte vengono cancellate.'),
  (gen_random_uuid()::text, 'it', 'ceabb049fdec4a34', 'Indichi l’istituzione della ricerca.'),
  (gen_random_uuid()::text, 'it', '2d507a78f7066401', 'Indichi chi risponde della ricerca.'),
  (gen_random_uuid()::text, 'it', '77ed48b810ebea84', 'Istituzione'),
  (gen_random_uuid()::text, 'it', 'a86fd6d19f0a6ad6', 'Minori di 18 anni'),
  (gen_random_uuid()::text, 'it', '1909140abac17e6c', 'Meno di 18 anni'),
  (gen_random_uuid()::text, 'it', '20fa6944319fc704', 'Nome del responsabile'),
  (gen_random_uuid()::text, 'it', '6a06a34354a2c160', 'Non c’è un beneficio diretto per lei. Le risposte aiutano a migliorare il prodotto valutato.'),
  (gen_random_uuid()::text, 'it', '5fe2fb303bbd5ee1', 'Il titolare del trattamento è il ricercatore responsabile dello studio, con nome e contatto nel modulo di consenso; lo strumento tratta i dati solo per suo conto.'),
  (gen_random_uuid()::text, 'it', '71f64806926ddb43', 'I partecipanti devono rivolgersi al ricercatore responsabile dello studio, il cui nome e contatto sono nel modulo di consenso.'),
  (gen_random_uuid()::text, 'it', 'ff188e9d3660a01b', 'I rischi sono minimi: rispondere può stancare un po’ o causare qualche disagio. Può interrompere in qualsiasi momento.'),
