  (gen_random_uuid()::text, 'cs', '20fa6944319fc704', 'Jméno odpovědné osoby'),
  (gen_random_uuid()::text, 'cs', '6a06a34354a2c160', 'Pro vás z účasti neplyne žádný přímý přínos. Odpovědi pomáhají zlepšit hodnocený produkt.'),
  (gen_random_uuid()::text, 'cs', '5fe2fb303bbd5ee1', 'Správcem údajů je výzkumník odpovědný za výzkum, jehož jméno a kontakt jsou v informovaném souhlasu; nástroj zpracovává údaje jen jeho jménem.'),
  (gen_random_uuid()::text, 'cs', '71f64806926ddb43', 'Účastníci se mají obrátit na výzkumníka odpovědného za výzkum, jehož jméno a kontakt jsou v informovaném souhlasu.'),
  (gen_random_uuid()::text, 'cs', 'ff188e9d3660a01b', 'Rizika jsou minimální: odpovídání může trochu unavit nebo způsobit určité nepohodlí. Kdykoli můžete přestat.'),
