  (gen_random_uuid()::text, 'cs', '8393f9735ff6ab2c', 'Odpovědná osoba za výzkum'),
  (gen_random_uuid()::text, 'cs', '0d2001e6b0e04ed4', 'Odpovědná osoba:'),
  (gen_random_uuid()::text, 'cs', '2d46c72a0dcdfbef', 'Rizika a přínosy'),
  (gen_random_uuid()::text, 'cs', 'f42e0f1d0b3ff09a', 'Rizika pro účastníka'),
  (gen_random_uuid()::text, 'cs', '81538cef7eca23ec', 'Pokud výzkum schválila etická komise, uveďte název komise, číslo stanoviska nebo CAAE a kontakt.'),
  (gen_random_uuid()::text, 'cs', 'f29c2be3f735e12d', 'Účastní se jen se souhlasem rodiče nebo zákonného zástupce, potvrzeným na první obrazovce (čl. 14).'),
