  (gen_random_uuid()::text, 'sk', '44e56e53751000e1', 'Etická komisia (nepovinné)'),
  (gen_random_uuid()::text, 'sk', '55ac540c97278766', 'Keďže odpovede nič nespája s vami, nemôžeme ich dohľadať, aby sme ich zobrazili alebo vymazali. Obráťte sa na zodpovedného výskumníka, ktorého kontakt je v informovanom súhlase.'),
