  (gen_random_uuid()::text, 'sl', '0a4db205367d4be0', 'Prikaže se v izjavi o soglasju: udeleženec mora vedeti, kdo odgovarja za raziskavo in kako to osebo doseže (LGPD, 9. člen).'),
  (gen_random_uuid()::text, 'sl', 'ec3869e76f1392d0', 'Prikažeta se v izjavi o soglasju. Orodje predlaga besedilo: prilagodite ga potrebam svoje raziskave.'),
  (gen_random_uuid()::text, 'sl', '14d4f1613366048b', '26 odgovorov na vprašalnik, različica izdelka, ki ste jo ocenili, jezik, datum, ali ste navedli, da ste mlajši od 18 let z dovoljenjem starša ali zastopnika, in samo če je raziskovalec vklopil ta korak in ste želeli odgovoriti, starostna skupina, spol, izobrazba in ali ste izdelek že uporabljali. Vsa ta vprašanja imajo »Raje ne odgovorim« in jih lahko preskočite.'),
  (gen_random_uuid()::text, 'sl', 'ca75ce9e25c59a83', 'Koristi'),
  (gen_random_uuid()::text, 'sl', '44e56e53751000e1', 'Etična komisija (neobvezno)'),
  (gen_random_uuid()::text, 'sl', '55ac540c97278766', 'Ker vas z odgovori nič ne povezuje, jih ne moremo najti, da bi jih prikazali ali izbrisali. Obrnite se na odgovornega raziskovalca, katerega stik je v izjavi o soglasju.'),
  (gen_random_uuid()::text, 'sl', '50b8d49b6a29d1b6', 'Od 4 do 6 minut · prostovoljno in anonimno'),
  (gen_random_uuid()::text, 'sl', 'ea58d1d62116f00e', 'Opišite koristi. Če neposredne koristi ni, to navedite.'),
  (gen_random_uuid()::text, 'sl', '06c2520553868965', 'Opišite tveganja za udeleženca. Če so minimalna, to navedite.'),
  (gen_random_uuid()::text, 'sl', '9269ccc0f5929fde', 'Kontaktni e-poštni naslov'),
  (gen_random_uuid()::text, 'sl', '573fdfeb95aa92fd', 'Dokler raziskovalec izvaja raziskavo. Ko raziskavo izbriše, se izbrišejo vsi odgovori.'),
  (gen_random_uuid()::text, 'sl', 'ceabb049fdec4a34', 'Navedite ustanovo raziskave.'),
  (gen_random_uuid()::text, 'sl', '2d507a78f7066401', 'Navedite, kdo odgovarja za raziskavo.'),
  (gen_random_uuid()::text, 'sl', '77ed48b810ebea84', 'Ustanova'),
  (gen_random_uuid()::text, 'sl', 'a86fd6d19f0a6ad6', 'Mlajši od 18 let'),
  (gen_random_uuid()::text, 'sl', '1909140abac17e6c', 'Manj kot 18 let'),
  (gen_random_uuid()::text, 'sl', '20fa6944319fc704', 'Ime odgovorne osebe'),
  (gen_random_uuid()::text, 'sl', '6a06a34354a2c160', 'Za vas ni neposredne koristi. Odgovori pomagajo izboljšati ocenjevani izdelek.'),
  (gen_random_uuid()::text, 'sl', '5fe2fb303bbd5ee1', 'Upravljavec podatkov je raziskovalec, odgovoren za raziskavo, katerega ime in stik sta v izjavi o soglasju; orodje podatke obdeluje le v njegovem imenu.'),
  (gen_random_uuid()::text, 'sl', '71f64806926ddb43', 'Udeleženci naj se obrnejo na raziskovalca, odgovornega za raziskavo, katerega ime in stik sta v izjavi o soglasju.'),
  (gen_random_uuid()::text, 'sl', 'ff188e9d3660a01b', 'Tveganja so minimalna: odgovarjanje vas lahko nekoliko utrudi ali povzroči nekaj nelagodja. Kadar koli lahko prenehate.'),
  (gen_random_uuid()::text, 'sl', 'e905fbd481b44379', 'Na primer: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'sl', '5acf07dbd38b18f1', 'Odgovorna oseba'),
  (gen_random_uuid()::text, 'sl', '8393f9735ff6ab2c', 'Odgovorna oseba za raziskavo'),
  (gen_random_uuid()::text, 'sl', '0d2001e6b0e04ed4', 'Odgovorna oseba:'),
  (gen_random_uuid()::text, 'sl', '2d46c72a0dcdfbef', 'Tveganja in koristi'),
  (gen_random_uuid()::text, 'sl', 'f42e0f1d0b3ff09a', 'Tveganja za udeleženca'),
  (gen_random_uuid()::text, 'sl', '81538cef7eca23ec', 'Če je raziskavo odobrila etična komisija, navedite ime komisije, številko mnenja ali CAAE in stik.'),
  (gen_random_uuid()::text, 'sl', 'f29c2be3f735e12d', 'Sodelujejo samo z dovoljenjem starša ali zakonitega zastopnika, potrjenim na prvem zaslonu (14. člen).'),
  (gen_random_uuid()::text, 'sl', 'ead048e033cd8fa6', 'Za koristi uporabite največ 1000 znakov.'),
  (gen_random_uuid()::text, 'sl', '41bf9e0ca889a640', 'Za tveganja uporabite največ 1000 znakov.'),
  (gen_random_uuid()::text, 'sl', '7ff5d65d41ecafd9', 'Za ustanovo uporabite največ 160 znakov.'),
  (gen_random_uuid()::text, 'sl', '85720a0a1823a83f', 'Za etično komisijo uporabite največ 500 znakov.'),
