  (gen_random_uuid()::text, 'kn', 'ec3869e76f1392d0', 'ಸಮ್ಮತಿ ಪತ್ರದಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ. ಉಪಕರಣವು ಒಂದು ಪಠ್ಯವನ್ನು ಸೂಚಿಸುತ್ತದೆ: ನಿಮ್ಮ ಅಧ್ಯಯನಕ್ಕೆ ಬೇಕಾದಂತೆ ಅದನ್ನು ಬದಲಿಸಿ.'),
  (gen_random_uuid()::text, 'kn', '14d4f1613366048b', 'ಪ್ರಶ್ನಾವಳಿಯ 26 ಉತ್ತರಗಳು, ನೀವು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿದ ಉತ್ಪನ್ನದ ಆವೃತ್ತಿ, ಭಾಷೆ, ದಿನಾಂಕ, ತಂದೆ-ತಾಯಿ ಅಥವಾ ಪೋಷಕರ ಅನುಮತಿಯೊಂದಿಗೆ ನಿಮ್ಮ ವಯಸ್ಸು 18ಕ್ಕಿಂತ ಕಡಿಮೆ ಎಂದು ತಿಳಿಸಿದ್ದೀರಾ ಎಂಬುದು, ಮತ್ತು ಸಂಶೋಧಕರು ಆ ಹಂತವನ್ನು ಆನ್ ಮಾಡಿ ನೀವು ಉತ್ತರಿಸಲು ಬಯಸಿದರೆ ಮಾತ್ರ ವಯೋಮಾನ, ಲಿಂಗ, ಶಿಕ್ಷಣ ಮತ್ತು ನೀವು ಈಗಾಗಲೇ ಉತ್ಪನ್ನವನ್ನು ಬಳಸುತ್ತಿದ್ದೀರಾ ಎಂಬುದು. ಈ ಎಲ್ಲ ಪ್ರಶ್ನೆಗಳಲ್ಲಿ “ಉತ್ತರಿಸಲು ಬಯಸುವುದಿಲ್ಲ” ಆಯ್ಕೆ ಇದೆ ಮತ್ತು ಅವನ್ನು ಬಿಟ್ಟುಬಿಡಬಹುದು.'),
  (gen_random_uuid()::text, 'kn', 'ca75ce9e25c59a83', 'ಪ್ರಯೋಜನಗಳು'),
  (gen_random_uuid()::text, 'kn', '44e56e53751000e1', 'ನೈತಿಕ ಸಮಿತಿ (ಐಚ್ಛಿಕ)'),
