  (gen_random_uuid()::text, 'ta', '0a4db205367d4be0', 'ஒப்புதல் படிவத்தில் தோன்றும்: ஆய்வுக்கு யார் பொறுப்பு, அவரை எப்படித் தொடர்புகொள்வது என்பதைப் பங்கேற்பாளர் அறிய வேண்டும் (LGPD, பிரிவு 9).'),
  (gen_random_uuid()::text, 'ta', 'ec3869e76f1392d0', 'ஒப்புதல் படிவத்தில் தோன்றும். கருவி ஒரு உரையைப் பரிந்துரைக்கிறது: உங்கள் ஆய்வுக்கு ஏற்ப அதை மாற்றுங்கள்.'),
  (gen_random_uuid()::text, 'ta', '14d4f1613366048b', 'கேள்வித்தாளின் 26 பதில்கள், நீங்கள் மதிப்பிட்ட தயாரிப்பின் பதிப்பு, மொழி, தேதி, பெற்றோர் அல்லது பாதுகாவலரின் அனுமதியுடன் நீங்கள் 18 வயதுக்குக் கீழ் என்று தெரிவித்தீர்களா என்பது, மேலும் ஆய்வாளர் அந்தப் படியை இயக்கியிருந்து நீங்கள் பதிலளிக்க விரும்பினால் மட்டும் வயதுப் பிரிவு, பாலினம், கல்வி, நீங்கள் ஏற்கனவே தயாரிப்பைப் பயன்படுத்தினீர்களா என்பது. இந்தக் கேள்விகள் அனைத்திலும் “பதிலளிக்க விரும்பவில்லை” என்ற தேர்வு உள்ளது, அவற்றைத் தவிர்க்கலாம்.'),
  (gen_random_uuid()::text, 'ta', 'ca75ce9e25c59a83', 'நன்மைகள்'),
  (gen_random_uuid()::text, 'ta', '44e56e53751000e1', 'அறநெறிக் குழு (விருப்பம்)'),
  (gen_random_uuid()::text, 'ta', '55ac540c97278766', 'பதில்களை உங்களுடன் எதுவும் இணைக்காததால், அவற்றைக் காட்டவோ நீக்கவோ எங்களால் கண்டுபிடிக்க முடியாது. ஒப்புதல் படிவத்தில் தொடர்பு விவரம் உள்ள பொறுப்பு ஆய்வாளரைத் தொடர்புகொள்ளுங்கள்.'),
  (gen_random_uuid()::text, 'ta', '50b8d49b6a29d1b6', '4 முதல் 6 நிமிடங்கள் · விருப்பத்தின் பேரில், அநாமதேயமாக'),
  (gen_random_uuid()::text, 'ta', 'ea58d1d62116f00e', 'நன்மைகளை விவரியுங்கள். நேரடி நன்மை இல்லையென்றால் அதைக் குறிப்பிடுங்கள்.'),
  (gen_random_uuid()::text, 'ta', '06c2520553868965', 'பங்கேற்பாளருக்கான இடர்களை விவரியுங்கள். அவை குறைவு என்றால் அதைக் குறிப்பிடுங்கள்.'),
  (gen_random_uuid()::text, 'ta', '9269ccc0f5929fde', 'தொடர்பு மின்னஞ்சல்'),
  (gen_random_uuid()::text, 'ta', '573fdfeb95aa92fd', 'ஆய்வாளர் ஆய்வை நடத்தும் வரை. அவர் ஆய்வை நீக்கும்போது எல்லாப் பதில்களும் அழிக்கப்படும்.'),
  (gen_random_uuid()::text, 'ta', 'ceabb049fdec4a34', 'ஆய்வின் நிறுவனத்தை உள்ளிடுங்கள்.'),
  (gen_random_uuid()::text, 'ta', '2d507a78f7066401', 'ஆய்வுக்கு யார் பொறுப்பு என்பதை உள்ளிடுங்கள்.'),
  (gen_random_uuid()::text, 'ta', '77ed48b810ebea84', 'நிறுவனம்'),
  (gen_random_uuid()::text, 'ta', 'a86fd6d19f0a6ad6', '18 வயதுக்குக் கீழ் உள்ளவர்கள்'),
  (gen_random_uuid()::text, 'ta', '1909140abac17e6c', '18 வயதுக்குக் கீழ்'),
  (gen_random_uuid()::text, 'ta', '20fa6944319fc704', 'பொறுப்பாளரின் பெயர்'),
  (gen_random_uuid()::text, 'ta', '6a06a34354a2c160', 'உங்களுக்கு நேரடி நன்மை எதுவும் இல்லை. பதில்கள் மதிப்பிடப்படும் தயாரிப்பை மேம்படுத்த உதவுகின்றன.'),
  (gen_random_uuid()::text, 'ta', '5fe2fb303bbd5ee1', 'தரவுக் கட்டுப்பாட்டாளர் ஆய்வுக்குப் பொறுப்பான ஆய்வாளர்; அவரின் பெயரும் தொடர்பு விவரமும் ஒப்புதல் படிவத்தில் உள்ளன; கருவி அவர் சார்பாக மட்டுமே தரவைக் கையாள்கிறது.'),
  (gen_random_uuid()::text, 'ta', '71f64806926ddb43', 'பங்கேற்பாளர்கள் ஆய்வுக்குப் பொறுப்பான ஆய்வாளரைத் தொடர்புகொள்ள வேண்டும்; அவரின் பெயரும் தொடர்பு விவரமும் ஒப்புதல் படிவத்தில் உள்ளன.'),
  (gen_random_uuid()::text, 'ta', 'ff188e9d3660a01b', 'இடர்கள் குறைவு: பதிலளிப்பது சற்றுச் சோர்வையோ சிறிது அசௌகரியத்தையோ ஏற்படுத்தலாம். எப்போது வேண்டுமானாலும் நிறுத்தலாம்.'),
  (gen_random_uuid()::text, 'ta', 'e905fbd481b44379', 'எடுத்துக்காட்டு: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'ta', '5acf07dbd38b18f1', 'பொறுப்பாளர்'),
  (gen_random_uuid()::text, 'ta', '8393f9735ff6ab2c', 'ஆய்வுக்குப் பொறுப்பானவர்'),
  (gen_random_uuid()::text, 'ta', '0d2001e6b0e04ed4', 'பொறுப்பாளர்:'),
  (gen_random_uuid()::text, 'ta', '2d46c72a0dcdfbef', 'இடர்களும் நன்மைகளும்'),
  (gen_random_uuid()::text, 'ta', 'f42e0f1d0b3ff09a', 'பங்கேற்பாளருக்கான இடர்கள்'),
  (gen_random_uuid()::text, 'ta', '81538cef7eca23ec', 'ஆய்வு ஓர் அறநெறிக் குழுவால் அங்கீகரிக்கப்பட்டிருந்தால், குழுவின் பெயர், கருத்துரை அல்லது CAAE எண், தொடர்பு விவரம் ஆகியவற்றை உள்ளிடுங்கள்.'),
  (gen_random_uuid()::text, 'ta', 'f29c2be3f735e12d', 'பெற்றோர் அல்லது சட்டப்பூர்வப் பாதுகாவலரின் அனுமதியுடன் மட்டுமே பங்கேற்பார்கள்; இது முதல் திரையில் உறுதிசெய்யப்படும் (பிரிவு 14).'),
  (gen_random_uuid()::text, 'ta', 'ead048e033cd8fa6', 'நன்மைகளுக்கு அதிகபட்சம் 1000 எழுத்துகள் பயன்படுத்துங்கள்.'),
  (gen_random_uuid()::text, 'ta', '41bf9e0ca889a640', 'இடர்களுக்கு அதிகபட்சம் 1000 எழுத்துகள் பயன்படுத்துங்கள்.'),
  (gen_random_uuid()::text, 'ta', '7ff5d65d41ecafd9', 'நிறுவனத்துக்கு அதிகபட்சம் 160 எழுத்துகள் பயன்படுத்துங்கள்.'),
  (gen_random_uuid()::text, 'ta', '85720a0a1823a83f', 'அறநெறிக் குழுவுக்கு அதிகபட்சம் 500 எழுத்துகள் பயன்படுத்துங்கள்.'),
  (gen_random_uuid()::text, 'ar', '9d1c35bc0063c2d5', '13 نوفمبر 2026'),
  (gen_random_uuid()::text, 'ar', '0a4db205367d4be0', 'يظهر في نموذج الموافقة: يحتاج المشارك إلى معرفة المسؤول عن البحث وكيفية التواصل معه (LGPD، المادة 9).'),
  (gen_random_uuid()::text, 'ar', 'ec3869e76f1392d0', 'يظهران في نموذج الموافقة. تقترح الأداة نصًا: عدّله بما يناسب دراستك.'),
  (gen_random_uuid()::text, 'ar', '14d4f1613366048b', 'الإجابات الـ26 في الاستبيان، ونسخة المنتج التي قيّمتها، واللغة، والتاريخ، وما إذا كنت قد صرّحت بأن عمرك أقل من 18 سنة بموافقة أحد والديك أو وليّ أمرك، وفقط إذا فعّل الباحث تلك المرحلة وأردت الإجابة: الفئة العمرية والجنس والمستوى التعليمي وما إذا كنت تستخدم المنتج من قبل. تحتوي كل هذه الأسئلة على «أفضّل عدم الإجابة» ويمكن تخطّيها.'),
  (gen_random_uuid()::text, 'ar', 'ca75ce9e25c59a83', 'الفوائد'),
  (gen_random_uuid()::text, 'ar', '44e56e53751000e1', 'لجنة الأخلاقيات (اختياري)'),
  (gen_random_uuid()::text, 'ar', '55ac540c97278766', 'بما أنه لا شيء يربط الإجابات بك، فلا يمكننا العثور عليها لعرضها أو حذفها. تواصل مع الباحث المسؤول، فبيانات التواصل معه موجودة في نموذج الموافقة.'),
  (gen_random_uuid()::text, 'ar', '50b8d49b6a29d1b6', 'من 4 إلى 6 دقائق · طوعية ومجهولة الهوية'),
  (gen_random_uuid()::text, 'ar', 'ea58d1d62116f00e', 'صِف الفوائد. إن لم تكن هناك فائدة مباشرة، فاذكر ذلك.'),
  (gen_random_uuid()::text, 'ar', '06c2520553868965', 'صِف المخاطر على المشارك. إن كانت ضئيلة، فاذكر ذلك.'),
  (gen_random_uuid()::text, 'ar', '9269ccc0f5929fde', 'بريد التواصل الإلكتروني'),
  (gen_random_uuid()::text, 'ar', '573fdfeb95aa92fd', 'ما دام الباحث يُجري البحث. وعندما يحذف الدراسة تُحذف جميع الإجابات.'),
  (gen_random_uuid()::text, 'ar', 'ceabb049fdec4a34', 'أدخل المؤسسة التي يتبع لها البحث.'),
  (gen_random_uuid()::text, 'ar', '2d507a78f7066401', 'أدخل المسؤول عن البحث.'),
  (gen_random_uuid()::text, 'ar', '77ed48b810ebea84', 'المؤسسة'),
  (gen_random_uuid()::text, 'ar', 'a86fd6d19f0a6ad6', 'من هم دون 18 سنة'),
  (gen_random_uuid()::text, 'ar', '1909140abac17e6c', 'أقل من 18 سنة'),
  (gen_random_uuid()::text, 'ar', '20fa6944319fc704', 'اسم المسؤول'),
  (gen_random_uuid()::text, 'ar', '6a06a34354a2c160', 'لا توجد فائدة مباشرة لك. تساعد الإجابات على تحسين المنتج الذي يجري تقييمه.'),
  (gen_random_uuid()::text, 'ar', '5fe2fb303bbd5ee1', 'المتحكم في البيانات هو الباحث المسؤول عن الدراسة، واسمه وبيانات التواصل معه في نموذج الموافقة؛ ولا تعالج الأداة البيانات إلا نيابةً عنه.'),
  (gen_random_uuid()::text, 'ar', '71f64806926ddb43', 'على المشاركين التواصل مع الباحث المسؤول عن الدراسة، واسمه وبيانات التواصل معه في نموذج الموافقة.'),
  (gen_random_uuid()::text, 'ar', 'ff188e9d3660a01b', 'المخاطر ضئيلة: قد تُتعبك الإجابة قليلًا أو تسبب لك بعض الانزعاج. يمكنك التوقف في أي وقت.'),
  (gen_random_uuid()::text, 'ar', 'e905fbd481b44379', 'مثال: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'ar', '5acf07dbd38b18f1', 'المسؤول عن البحث'),
  (gen_random_uuid()::text, 'ar', '8393f9735ff6ab2c', 'المسؤول عن البحث'),
  (gen_random_uuid()::text, 'ar', '0d2001e6b0e04ed4', 'المسؤول عن البحث:'),
  (gen_random_uuid()::text, 'ar', '2d46c72a0dcdfbef', 'المخاطر والفوائد'),
  (gen_random_uuid()::text, 'ar', 'f42e0f1d0b3ff09a', 'المخاطر على المشارك'),
  (gen_random_uuid()::text, 'ar', '81538cef7eca23ec', 'إذا وافقت لجنة أخلاقيات على الدراسة، فأدخل اسم اللجنة ورقم القرار أو CAAE وبيانات التواصل.'),
  (gen_random_uuid()::text, 'ar', 'f29c2be3f735e12d', 'لا يشاركون إلا بموافقة أحد الوالدين أو وليّ الأمر القانوني، ويُؤكَّد ذلك في الشاشة الأولى (المادة 14).'),
  (gen_random_uuid()::text, 'ar', 'ead048e033cd8fa6', 'استخدم 1000 حرف كحد أقصى للفوائد.'),
  (gen_random_uuid()::text, 'ar', '41bf9e0ca889a640', 'استخدم 1000 حرف كحد أقصى للمخاطر.'),
  (gen_random_uuid()::text, 'ar', '7ff5d65d41ecafd9', 'استخدم 160 حرفًا كحد أقصى للمؤسسة.'),
  (gen_random_uuid()::text, 'ar', '85720a0a1823a83f', 'استخدم 500 حرف كحد أقصى للجنة الأخلاقيات.'),
  (gen_random_uuid()::text, 'he', '9d1c35bc0063c2d5', '13 בנובמבר 2026'),
  (gen_random_uuid()::text, 'he', '0a4db205367d4be0', 'מופיע בטופס ההסכמה: המשתתף צריך לדעת מי אחראי למחקר ואיך ליצור איתו קשר (LGPD, סעיף 9).'),
  (gen_random_uuid()::text, 'he', 'ec3869e76f1392d0', 'מופיעים בטופס ההסכמה. הכלי מציע נוסח: יש להתאים אותו לצורכי המחקר.'),
  (gen_random_uuid()::text, 'he', '14d4f1613366048b', '26 התשובות לשאלון, גרסת המוצר שהוערכה, השפה, התאריך, האם הוצהר על גיל מתחת ל־18 באישור הורה או אפוטרופוס, ורק אם החוקר הפעיל את השלב הזה והייתה רצון לענות, קבוצת הגיל, המגדר, ההשכלה והאם המוצר כבר היה בשימוש. בכל השאלות האלה יש „מעדיף/ה לא לענות” ואפשר לדלג עליהן.'),
  (gen_random_uuid()::text, 'he', 'ca75ce9e25c59a83', 'תועלות'),
  (gen_random_uuid()::text, 'he', '44e56e53751000e1', 'ועדת אתיקה (רשות)'),
  (gen_random_uuid()::text, 'he', '55ac540c97278766', 'מכיוון ששום דבר לא מקשר את התשובות אליך, אין לנו אפשרות למצוא אותן כדי להציג או למחוק אותן. יש לפנות לחוקר האחראי, שפרטי הקשר שלו מופיעים בטופס ההסכמה.'),
  (gen_random_uuid()::text, 'he', '50b8d49b6a29d1b6', '4 עד 6 דקות · מרצון ובאופן אנונימי'),
  (gen_random_uuid()::text, 'he', 'ea58d1d62116f00e', 'יש לתאר את התועלות. אם אין תועלת ישירה, יש לציין זאת.'),
  (gen_random_uuid()::text, 'he', '06c2520553868965', 'יש לתאר את הסיכונים למשתתף. אם הם מזעריים, יש לציין זאת.'),
  (gen_random_uuid()::text, 'he', '9269ccc0f5929fde', 'דוא״ל ליצירת קשר'),
  (gen_random_uuid()::text, 'he', '573fdfeb95aa92fd', 'כל עוד החוקר מבצע את המחקר. כשהוא מוחק את המחקר, כל התשובות נמחקות.'),
  (gen_random_uuid()::text, 'he', 'ceabb049fdec4a34', 'יש להזין את המוסד של המחקר.'),
  (gen_random_uuid()::text, 'he', '2d507a78f7066401', 'יש להזין מי אחראי למחקר.'),
  (gen_random_uuid()::text, 'he', '77ed48b810ebea84', 'מוסד'),
  (gen_random_uuid()::text, 'he', 'a86fd6d19f0a6ad6', 'מתחת לגיל 18'),
  (gen_random_uuid()::text, 'he', '1909140abac17e6c', 'מתחת לגיל 18'),
  (gen_random_uuid()::text, 'he', '20fa6944319fc704', 'שם האחראי'),
  (gen_random_uuid()::text, 'he', '6a06a34354a2c160', 'אין תועלת ישירה עבורך. התשובות עוזרות לשפר את המוצר שמוערך.'),
  (gen_random_uuid()::text, 'he', '5fe2fb303bbd5ee1', 'בעל השליטה בנתונים הוא החוקר האחראי למחקר, ששמו ופרטי הקשר שלו מופיעים בטופס ההסכמה; הכלי מעבד את הנתונים רק בשמו.'),
  (gen_random_uuid()::text, 'he', '71f64806926ddb43', 'המשתתפים צריכים לפנות לחוקר האחראי למחקר, ששמו ופרטי הקשר שלו מופיעים בטופס ההסכמה.'),
  (gen_random_uuid()::text, 'he', 'ff188e9d3660a01b', 'הסיכונים מזעריים: המענה עלול לעייף מעט או לגרום אי־נוחות מסוימת. אפשר להפסיק בכל רגע.'),
  (gen_random_uuid()::text, 'he', 'e905fbd481b44379', 'לדוגמה: PPGIa · PUCPR.'),
  (gen_random_uuid()::text, 'he', '5acf07dbd38b18f1', 'האחראי למחקר'),
  (gen_random_uuid()::text, 'he', '8393f9735ff6ab2c', 'האחראי למחקר'),
  (gen_random_uuid()::text, 'he', '0d2001e6b0e04ed4', 'האחראי למחקר:'),
  (gen_random_uuid()::text, 'he', '2d46c72a0dcdfbef', 'סיכונים ותועלות'),
  (gen_random_uuid()::text, 'he', 'f42e0f1d0b3ff09a', 'סיכונים למשתתף'),
  (gen_random_uuid()::text, 'he', '81538cef7eca23ec', 'אם המחקר אושר בוועדת אתיקה, יש להזין את שם הוועדה, מספר ההחלטה או CAAE ופרטי קשר.'),
  (gen_random_uuid()::text, 'he', 'f29c2be3f735e12d', 'משתתפים רק באישור הורה או אפוטרופוס חוקי, שמאושר במסך הראשון (סעיף 14).'),
  (gen_random_uuid()::text, 'he', 'ead048e033cd8fa6', 'יש להשתמש בעד 1000 תווים לתועלות.'),
  (gen_random_uuid()::text, 'he', '41bf9e0ca889a640', 'יש להשתמש בעד 1000 תווים לסיכונים.'),
  (gen_random_uuid()::text, 'he', '7ff5d65d41ecafd9', 'יש להשתמש בעד 160 תווים למוסד.'),
  (gen_random_uuid()::text, 'he', '85720a0a1823a83f', 'יש להשתמש בעד 500 תווים לוועדת האתיקה.'),
  (gen_random_uuid()::text, 'fa', '9d1c35bc0063c2d5', '۱۳ نوامبر ۲۰۲۶'),
  (gen_random_uuid()::text, 'fa', '0a4db205367d4be0', 'در فرم رضایت آگاهانه نمایش داده می‌شود: شرکت‌کننده باید بداند چه کسی مسئول پژوهش است و چگونه با او تماس بگیرد (LGPD، مادهٔ ۹).'),
  (gen_random_uuid()::text, 'fa', 'ec3869e76f1392d0', 'در فرم رضایت آگاهانه نمایش داده می‌شوند. ابزار متنی پیشنهاد می‌کند: آن را با نیاز پژوهش خود هماهنگ کنید.'),
  (gen_random_uuid()::text, 'fa', '14d4f1613366048b', '۲۶ پاسخ پرسش‌نامه، نسخهٔ محصولی که ارزیابی کردید، زبان، تاریخ، اینکه آیا با اجازهٔ پدر یا مادر یا سرپرست اعلام کرده‌اید کمتر از ۱۸ سال دارید، و فقط اگر پژوهشگر آن مرحله را فعال کرده باشد و شما بخواهید پاسخ دهید، گروه سنی، جنسیت، تحصیلات و اینکه آیا قبلاً از محصول استفاده می‌کردید. همهٔ این پرسش‌ها گزینهٔ «ترجیح می‌دهم پاسخ ندهم» دارند و می‌توان از آن‌ها گذشت.'),
  (gen_random_uuid()::text, 'fa', 'ca75ce9e25c59a83', 'فایده‌ها'),
  (gen_random_uuid()::text, 'fa', '44e56e53751000e1', 'کمیتهٔ اخلاق (اختیاری)'),
  (gen_random_uuid()::text, 'fa', '55ac540c97278766', 'چون هیچ چیز پاسخ‌ها را به شما مرتبط نمی‌کند، نمی‌توانیم آن‌ها را برای نمایش یا حذف پیدا کنیم. با پژوهشگر مسئول تماس بگیرید؛ اطلاعات تماس او در فرم رضایت آگاهانه است.'),
  (gen_random_uuid()::text, 'fa', '50b8d49b6a29d1b6', '۴ تا ۶ دقیقه · داوطلبانه و ناشناس'),
  (gen_random_uuid()::text, 'fa', 'ea58d1d62116f00e', 'فایده‌ها را شرح دهید. اگر فایدهٔ مستقیمی وجود ندارد، این را بنویسید.'),
  (gen_random_uuid()::text, 'fa', '06c2520553868965', 'خطرها برای شرکت‌کننده را شرح دهید. اگر اندک‌اند، این را بنویسید.'),
  (gen_random_uuid()::text, 'fa', '9269ccc0f5929fde', 'ایمیل تماس'),
  (gen_random_uuid()::text, 'fa', '573fdfeb95aa92fd', 'تا زمانی که پژوهشگر پژوهش را انجام می‌دهد. وقتی مطالعه را حذف کند، همهٔ پاسخ‌ها پاک می‌شوند.'),
  (gen_random_uuid()::text, 'fa', 'ceabb049fdec4a34', 'مؤسسهٔ پژوهش را وارد کنید.'),
  (gen_random_uuid()::text, 'fa', '2d507a78f7066401', 'مسئول پژوهش را وارد کنید.'),
  (gen_random_uuid()::text, 'fa', '77ed48b810ebea84', 'مؤسسه'),
  (gen_random_uuid()::text, 'fa', 'a86fd6d19f0a6ad6', 'افراد زیر ۱۸ سال'),
  (gen_random_uuid()::text, 'fa', '1909140abac17e6c', 'کمتر از ۱۸ سال'),
  (gen_random_uuid()::text, 'fa', '20fa6944319fc704', 'نام مسئول'),
  (gen_random_uuid()::text, 'fa', '6a06a34354a2c160', 'فایدهٔ مستقیمی برای شما ندارد. پاسخ‌ها به بهبود محصول ارزیابی‌شده کمک می‌کنند.'),
  (gen_random_uuid()::text, 'fa', '5fe2fb303bbd5ee1', 'کنترل‌کنندهٔ داده‌ها پژوهشگر مسئول مطالعه است که نام و اطلاعات تماسش در فرم رضایت آگاهانه آمده؛ ابزار فقط از طرف او داده‌ها را پردازش می‌کند.'),
  (gen_random_uuid()::text, 'fa', '71f64806926ddb43', 'شرکت‌کنندگان باید با پژوهشگر مسئول مطالعه تماس بگیرند؛ نام و اطلاعات تماس او در فرم رضایت آگاهانه آمده است.'),
  (gen_random_uuid()::text, 'fa', 'ff188e9d3660a01b', 'خطرها اندک‌اند: پاسخ دادن ممکن است کمی خسته‌کننده باشد یا اندکی ناراحتی ایجاد کند. هر زمان بخواهید می‌توانید متوقف شوید.'),
  (gen_random_uuid()::text, 'fa', 'e905fbd481b44379', 'برای مثال: PPGIa · PUCPR.'),
