  (gen_random_uuid()::text, 'fa', '0d2001e6b0e04ed4', 'مسئول پژوهش:'),
  (gen_random_uuid()::text, 'fa', '2d46c72a0dcdfbef', 'خطرها و فایده‌ها'),
  (gen_random_uuid()::text, 'fa', 'f42e0f1d0b3ff09a', 'خطرها برای شرکت‌کننده'),
  (gen_random_uuid()::text, 'fa', '81538cef7eca23ec', 'اگر مطالعه را کمیتهٔ اخلاق تأیید کرده است، نام کمیته، شمارهٔ نظر یا CAAE و اطلاعات تماس را وارد کنید.'),
  (gen_random_uuid()::text, 'fa', 'f29c2be3f735e12d', 'فقط با اجازهٔ پدر یا مادر یا سرپرست قانونی شرکت می‌کنند که در صفحهٔ اول تأیید می‌شود (مادهٔ ۱۴).'),
